const SEED_COUNT = 50;

// Clinic ID counter for sequential generation (CL0001, CL0002, etc.)
// Starts at 2 to ensure Aadesh Ayurvedalay gets CL0002
let clinicIdCounter = 2;

/**
 * Generate sequential clinic ID in format CL0001, CL0002, etc.
 * Format matches ClinicService.generateNextClinicId() implementation
 */
function generateClinicId(): string {
  return `CL${String(clinicIdCounter++).padStart(4, '0')}`;
}

function createFallbackFaker(): any {
  const pick = <T>(values: T[]): T => values[Math.floor(Math.random() * values.length)]!;
  const int = (min: number, max: number): number =>
    Math.floor(Math.random() * (max - min + 1)) + min;
  const float = (min: number, max: number, fractionDigits = 1): number =>
    Number((Math.random() * (max - min) + min).toFixed(fractionDigits));
  const uuid = (): string =>
    'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, char => {
      const value = Math.random() * 16;
      const hex = char === 'x' ? value : (value & 0x3) | 0x8;
      return Math.floor(hex).toString(16);
    });
  const makeWord = (prefix: string): string =>
    `${prefix}-${Math.random().toString(36).slice(2, 8)}`;

  return {
    internet: {
      email: (): string => `user.${Math.random().toString(36).slice(2, 10)}@example.com`,
      password: (): string => `pass-${Math.random().toString(36).slice(2, 10)}`,
    },
    person: {
      fullName: (): string =>
        `${pick(['Alex', 'Sam', 'Priya', 'Ravi', 'Anita'])} ${pick(['Shah', 'Patel', 'Kumar', 'Joshi', 'Mehta'])}`,
      firstName: (): string => pick(['Alex', 'Sam', 'Priya', 'Ravi', 'Anita']),
      lastName: (): string => pick(['Shah', 'Patel', 'Kumar', 'Joshi', 'Mehta']),
      jobTitle: (): string =>
        pick(['Physician', 'Therapist', 'Consultant', 'Assistant', 'Specialist']),
      jobType: (): string => pick(['Full-time', 'Part-time', 'Contract', 'Consulting']),
    },
    number: {
      int: ({ min, max }: { min: number; max: number }): number => int(min, max),
      float: ({
        min,
        max,
        fractionDigits,
      }: {
        min: number;
        max: number;
        fractionDigits?: number;
      }): number => float(min, max, fractionDigits ?? 1),
    },
    phone: {
      number: (): string => `+91-${int(7000000000, 9999999999)}`,
    },
    helpers: {
      arrayElement: <T>(values: T[]): T => pick(values),
      weightedArrayElement: <T>(values: Array<{ weight: number; value: T }>): T =>
        values.find(entry => entry.weight === Math.max(...values.map(v => v.weight)))?.value ??
        values[0]!.value,
    },
    date: {
      future: (): Date => new Date(Date.now() + int(1, 30) * 24 * 60 * 60 * 1000),
      past: (): Date => new Date(Date.now() - int(1, 30) * 24 * 60 * 60 * 1000),
      recent: (): Date => new Date(Date.now() - int(0, 7) * 24 * 60 * 60 * 1000),
    },
    location: {
      latitude: (): number => Number((Math.random() * 180 - 90).toFixed(6)),
      longitude: (): number => Number((Math.random() * 360 - 180).toFixed(6)),
    },
    commerce: {
      productName: (): string => makeWord('product'),
      productMaterial: (): string => pick(['herbal blend', 'powder', 'tablet', 'oil']),
      productDescription: (): string => makeWord('description'),
    },
    company: {
      name: (): string => pick(['Aadesh Labs', 'Ayur Wellness', 'Herbal Care', 'Veda Health']),
    },
    string: {
      uuid,
    },
    lorem: {
      sentence: (): string => 'Demo seed generated by fallback faker.',
    },
  };
}

const faker: any = (() => {
  try {
    return _requireModule('@faker-js/faker').faker;
  } catch {
    return createFallbackFaker();
  }
})();

